;
; SDP fmtp line definition
;

fmtp = "a=fmtp:" token SP param-assign 0*(";" SP param-assign) CRLF

;
; mpeg4-generic mode parameter extension
;

mode               =/ "rtp-midi"
                   ; as described in Section 6.2 of this memo
